CREATE TABLE repository_meta (key TEXT PRIMARY KEY NOT NULL, revision INTEGER NOT NULL CHECK (revision >= 0));
CREATE TABLE learners (id TEXT PRIMARY KEY NOT NULL, data TEXT NOT NULL);
CREATE TABLE vocabulary_assessments (id TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id), data TEXT NOT NULL);
CREATE TABLE vocabulary_assessment_tasks (id TEXT PRIMARY KEY NOT NULL, assessment_id TEXT NOT NULL REFERENCES vocabulary_assessments(id), position INTEGER NOT NULL CHECK (position >= 0), data TEXT NOT NULL);
CREATE TABLE vocabulary_assessment_attempts (id TEXT PRIMARY KEY NOT NULL, assessment_id TEXT NOT NULL REFERENCES vocabulary_assessments(id), task_id TEXT NOT NULL REFERENCES vocabulary_assessment_tasks(id), data TEXT NOT NULL);
CREATE TABLE materials (id TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id), data TEXT NOT NULL);
CREATE TABLE material_analyses (id TEXT PRIMARY KEY NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), data TEXT NOT NULL);
CREATE TABLE knowledge_points (id TEXT PRIMARY KEY NOT NULL, data TEXT NOT NULL);
CREATE TABLE material_analysis_items (analysis_id TEXT NOT NULL REFERENCES material_analyses(id), knowledge_point_id TEXT NOT NULL REFERENCES knowledge_points(id), position INTEGER NOT NULL CHECK (position >= 0), data TEXT NOT NULL, UNIQUE(analysis_id, knowledge_point_id));
CREATE TABLE material_analysis_occurrences (analysis_id TEXT NOT NULL, knowledge_point_id TEXT NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), data TEXT NOT NULL, PRIMARY KEY(analysis_id, knowledge_point_id, position), FOREIGN KEY(analysis_id, knowledge_point_id) REFERENCES material_analysis_items(analysis_id, knowledge_point_id));
CREATE TABLE material_analysis_unmatched_items (analysis_id TEXT NOT NULL REFERENCES material_analyses(id), position INTEGER NOT NULL CHECK (position >= 0), data TEXT NOT NULL, PRIMARY KEY(analysis_id, position));
CREATE TABLE material_analysis_unmatched_occurrences (analysis_id TEXT NOT NULL, item_position INTEGER NOT NULL CHECK (item_position >= 0), position INTEGER NOT NULL CHECK (position >= 0), data TEXT NOT NULL, PRIMARY KEY(analysis_id, item_position, position), FOREIGN KEY(analysis_id, item_position) REFERENCES material_analysis_unmatched_items(analysis_id, position));
CREATE TABLE learning_goals (id TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id), data TEXT NOT NULL);
CREATE TABLE goal_materials (goal_id TEXT NOT NULL REFERENCES learning_goals(id), material_id TEXT NOT NULL REFERENCES materials(id), data TEXT NOT NULL, PRIMARY KEY(goal_id, material_id));
CREATE TABLE goal_knowledge_points (goal_id TEXT NOT NULL REFERENCES learning_goals(id), knowledge_point_id TEXT NOT NULL REFERENCES knowledge_points(id), data TEXT NOT NULL, PRIMARY KEY(goal_id, knowledge_point_id));
CREATE TABLE goal_knowledge_point_sources (goal_id TEXT NOT NULL, knowledge_point_id TEXT NOT NULL, source_analysis_id TEXT NOT NULL REFERENCES material_analyses(id), data TEXT NOT NULL, PRIMARY KEY(goal_id, knowledge_point_id, source_analysis_id), FOREIGN KEY(goal_id, knowledge_point_id) REFERENCES goal_knowledge_points(goal_id, knowledge_point_id));
CREATE TABLE knowledge_point_vocabulary_classifications (key TEXT PRIMARY KEY NOT NULL, knowledge_point_id TEXT NOT NULL REFERENCES knowledge_points(id), data TEXT NOT NULL);
CREATE TABLE learner_knowledge_points (key TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id), knowledge_point_id TEXT NOT NULL REFERENCES knowledge_points(id), data TEXT NOT NULL);
CREATE TABLE study_plans (id TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id), date TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(learner_id, date));
CREATE TABLE learning_tasks (id TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id), goal_id TEXT NOT NULL REFERENCES learning_goals(id), data TEXT NOT NULL);
CREATE TABLE study_plan_tasks (plan_id TEXT NOT NULL REFERENCES study_plans(id), task_id TEXT NOT NULL REFERENCES learning_tasks(id), position INTEGER NOT NULL CHECK (position >= 0), PRIMARY KEY(plan_id, task_id), UNIQUE(plan_id, position));
CREATE TABLE task_attempts (id TEXT PRIMARY KEY NOT NULL, task_id TEXT NOT NULL REFERENCES learning_tasks(id), learner_id TEXT NOT NULL REFERENCES learners(id), data TEXT NOT NULL, UNIQUE(task_id));
CREATE INDEX study_plans_learner_date_idx ON study_plans(learner_id, date);
CREATE INDEX tasks_goal_idx ON learning_tasks(goal_id);
CREATE INDEX attempts_learner_idx ON task_attempts(learner_id);
CREATE INDEX material_analyses_material_idx ON material_analyses(material_id);
CREATE INDEX goal_materials_material_idx ON goal_materials(material_id);
CREATE INDEX goal_sources_analysis_idx ON goal_knowledge_point_sources(source_analysis_id);
CREATE INDEX learner_kp_lookup_idx ON learner_knowledge_points(learner_id, knowledge_point_id);
CREATE INDEX analysis_items_kp_idx ON material_analysis_items(knowledge_point_id);
